package com.vision.iptv;
import android.app.*;
import android.content.*;
import android.os.*;
import java.io.*;
import org.json.*;

public final class RecordingService extends Service {
 static volatile boolean active=false;
 static final String CHANNEL="vision_recording";
 private final Recorder recorder=new Recorder();
 private final Handler handler=new Handler(Looper.getMainLooper());
 private SharedPreferences prefs;
 private PowerManager.WakeLock wake;
 private long end=0;
 private String title="";
 private boolean stopping=false,exporting=false;
 private final Runnable tick=new Runnable(){public void run(){check();if(!stopping)handler.postDelayed(this,5000);}};
 @Override public void onCreate(){super.onCreate();prefs=PrivatePreferences.open(this);if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CHANNEL,"Запись IPTV",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(c);}PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);wake=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"VisionIPTV:recording");wake.setReferenceCounted(false);}
 private Notification notification(String message){Intent open=new Intent(this,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Intent stop=new Intent(this,RecordingService.class).setAction("stop");PendingIntent si=PendingIntent.getService(this,1,stop,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);return b.setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("Vision IPTV Pro").setContentText(message).setContentIntent(pi).setOngoing(true).addAction(android.R.drawable.ic_menu_close_clear_cancel,"Остановить запись",si).build();}
 private void show(String message){getSystemService(NotificationManager.class).notify(81,notification(message));}
 @Override public int onStartCommand(Intent intent,int flags,int id){startForeground(81,notification("Подготовка записи"));if(intent!=null&&"stop".equals(intent.getAction())){recorder.stop();end=0;}else if(intent!=null&&"record".equals(intent.getAction())&&recorder.worker==null&&!exporting){String url=intent.getStringExtra("url");if(url!=null)begin(url,intent.getStringExtra("title"),0);}handler.removeCallbacks(tick);handler.post(tick);return START_NOT_STICKY;}
 private void begin(String url,String name,long until){File dir=new File(getFilesDir(),"recordings");dir.mkdirs();title=name==null?"Канал":name;String safe=title.replaceAll("[^\\p{L}\\p{N} _-]","_").trim();if(safe.length()>80)safe=safe.substring(0,80);File file=new File(dir,new java.text.SimpleDateFormat("yyyy-MM-dd_HH-mm-ss",java.util.Locale.US).format(new java.util.Date())+"_"+safe+"_"+java.util.UUID.randomUUID().toString().substring(0,8)+".ts");String destination=prefs.getString("recordTree",""),nas=prefs.getString("recordNas","");String nasId=prefs.getString("recordNasId","");boolean direct=prefs.getBoolean("recordDirect",false)&&(!destination.isEmpty()||!nas.isEmpty());recorder.destination=direct?()->!destination.isEmpty()?openTree(destination,file.getName()):openNas(nas+android.net.Uri.encode(file.getName()),nasId):null;end=until;recorder.retentionCleanup=direct?null:()->cleanupExpired(dir);recorder.maxHeight=prefs.getInt("recordMaxHeight",0);recorder.quotaBytes=direct?0:prefs.getInt("recordQuotaGb",0)*1073741824L;recorder.userAgent=prefs.getString("streamUserAgent","VisionIPTV/1.0");if(recorder.start(url,file,()->handler.post(()->{end=0;String result=recorder.lastError.isEmpty()?((direct?recorder.written>0:file.length()>0)?(direct?"Запись сохранена на внешнем накопителе":"Запись сохранена"):"Запись не создана"):"Ошибка записи: "+recorder.lastError+(direct?" • возможна частичная запись на накопителе":"");if(!direct&&file.length()>0&&(!destination.isEmpty()||!nas.isEmpty())){exporting=true;show("Копирование записи на накопитель");new Thread(()->{String message=result;try{if(!destination.isEmpty())copyToTree(destination,file);else{String[] auth=nasAuth(nasId);SmbStorage.upload(nas+android.net.Uri.encode(file.getName()),auth[0],auth[1],file);}message+=" • копия сохранена";}catch(Exception e){message+=" • ошибка копирования, оригинал сохранён";}String done=message;handler.post(()->{exporting=false;active=false;prefs.edit().putString("lastRecordingResult",done).apply();if(!stopping)check();});},"RecordingExport").start();}else{active=false;prefs.edit().putString("lastRecordingResult",result).apply();if(!stopping)check();}}))){active=true;if(!wake.isHeld())wake.acquire(12L*60*60*1000);show("Запись • "+title);}}
 private void check(){if(stopping||exporting)return;long now=System.currentTimeMillis();if(recorder.worker!=null){if(end>0&&now>=end)recorder.stop();return;}boolean pending=false;try{JSONArray a=new JSONArray(prefs.getString("scheduled","[]"));boolean changed=false;for(int i=a.length()-1;i>=0;i--){JSONObject o=a.getJSONObject(i);if(o.getLong("end")<=now){a.remove(i);changed=true;continue;}pending=true;if(o.getLong("start")<=now&&recorder.worker==null){begin(o.getString("url"),o.optString("title"),o.getLong("end"));a.remove(i);changed=true;}}if(changed)prefs.edit().putString("scheduled",a.toString()).apply();pending=a.length()>0;}catch(Exception ignored){}if(recorder.worker==null&&!pending){stopping=true;stopForeground(true);stopSelf();return;}if(!wake.isHeld())wake.acquire(12L*60*60*1000);if(recorder.worker==null)show("Ожидание записи по расписанию");}
 private void cleanupExpired(File dir){int days=prefs.getInt("recordRetentionDays",0);if(days!=7&&days!=14&&days!=30&&days!=60&&days!=90)return;long cutoff=System.currentTimeMillis()-days*86400000L;File[] files=dir.listFiles((d,n)->n.endsWith(".ts"));int removed=0;if(files!=null)for(File file:files){if(!recorder.running)break; synchronized(RecordingService.class){if(file.isFile()&&file.lastModified()>0&&file.lastModified()<cutoff&&!prefs.getStringSet("protectedRecordings",java.util.Collections.emptySet()).contains(file.getName())&&file.delete())removed++;}}prefs.edit().putInt("lastRetentionRemoved",removed).apply();}
 private String[] nasAuth(String id)throws Exception{return id.isEmpty()?new String[]{"",""}:NasSecrets.read(this,id);}
 private OutputStream openNas(String address,String id)throws Exception{String[] auth=nasAuth(id);return SmbStorage.openRecording(address,auth[0],auth[1]);}
 private OutputStream openTree(String tree,String name)throws Exception{android.net.Uri root=android.net.Uri.parse(tree);android.net.Uri parent=android.provider.DocumentsContract.buildDocumentUriUsingTree(root,android.provider.DocumentsContract.getTreeDocumentId(root));android.net.Uri dest=android.provider.DocumentsContract.createDocument(getContentResolver(),parent,"video/mp2t",name);if(dest==null)throw new IOException("Не удалось создать файл на накопителе");OutputStream stream=getContentResolver().openOutputStream(dest,"w");if(stream==null)throw new IOException("Не удалось открыть файл на накопителе");return stream;}
 private void copyToTree(String tree,File file)throws Exception{android.net.Uri root=android.net.Uri.parse(tree);android.net.Uri parent=android.provider.DocumentsContract.buildDocumentUriUsingTree(root,android.provider.DocumentsContract.getTreeDocumentId(root));android.net.Uri dest=android.provider.DocumentsContract.createDocument(getContentResolver(),parent,"video/mp2t",file.getName());if(dest==null)throw new IOException("Cannot create file");try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(dest,"w")){if(out==null)throw new IOException("Cannot open file");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}catch(Exception e){try{android.provider.DocumentsContract.deleteDocument(getContentResolver(),dest);}catch(Exception ignored){}throw e;}}
 @Override public void onDestroy(){stopping=true;handler.removeCallbacksAndMessages(null);recorder.stop();active=false;if(wake!=null&&wake.isHeld())wake.release();super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
}
